  } ]
}, {
  "tStartMs": 1033899,
  "dDurationMs": 1335,
  "segs": [ {

text:
    "utf8": "甚至我必須這麼說 "
  } ]
}, {
  "tStartMs": 1035234,
  "dDurationMs": 1868,
  "segs": [ {
    "utf8": "連候選人推出來"
  } ]
}, {
  "tStartMs": 1037102,
  "dDurationMs": 1802,
  "segs": [ {
    "utf8": "上一次是上一個世代"
  } ]
}, {
  "tStartMs": 1038904,
  "dDurationMs": 3086,
  "segs": [ {
    "utf8": "這一次又是比我們年輕的世代"
  } ]
}, {
  "tStartMs": 1041990,
  "dDurationMs": 3204,
  "segs": [ {
    "utf8": "你怎麼去照顧到這個族群"
  } ]
}, {
  "tStartMs": 1045194,
  "dDurationMs": 1401,
  "segs": [ {
    "utf8": "他們心裡的這種"
  } ]
}, {
  "tStartMs": 1046595,
  "dDurationMs": 1185,
  "segs": [ {
    "utf8": "可能不平也好 "
  } ]
}, {
  "tStartMs": 1047780,
  "dDurationMs": 884,
  "segs": [ {
    "utf8": "失落也好"
  } ]
}, {
  "tStartMs": 1048664,
  "dDurationMs": 2702,
  "segs": [ {
    "utf8": "我覺得有好幾個層次 "
  } ]
}, {
  "tStartMs": 1051366,
  "dDurationMs": 1852,
  "segs": [ {
    "utf8": "就是說應該這樣講"
  } ]
}, {
  "tStartMs": 1053218,
  "dDurationMs": 2536,
  "segs": [ {
    "utf8": "我們覺得照顧這個城市的每一個人"
  } ]
}, {
  "tStartMs": 1055754,
  "dDurationMs": 818,
  "segs": [ {
    "utf8": "其實是 "
  } ]
}, {
  "tStartMs": 1056572,
  "dDurationMs": 1084,
  "segs": [ {
    "utf8": "我們第一個 "
  } ]
}, {
  "tStartMs": 1057656,
  "dDurationMs": 1018,
  "segs": [ {
    "utf8": "大家最容易想到的"
  } ]
}, {
  "tStartMs": 1058674,
  "dDurationMs": 1968,
  "segs": [ {
    "utf8": "都是心理的照顧 "
  } ]
}, {
  "tStartMs": 1060642,
  "dDurationMs": 2153,
  "segs": [ {
    "utf8": "我們有多一點活動"
  } ]
}, {
  "tStartMs": 1062795,
  "dDurationMs": 2002,
  "segs": [ {
    "utf8": "多一點諮商什麼等等之類的"
  } ]
}, {
  "tStartMs": 1064797,
  "dDurationMs": 1701,
  "segs": [ {
    "utf8": "但我一直都覺得一個城市"
  } ]
}, {
  "tStartMs": 1066498,
  "dDurationMs": 2303,
  "segs": [ {
    "utf8": "要去照顧到每一個人的第一件事情"
  } ]
}, {
  "tStartMs": 1068801,
  "dDurationMs": 1217,
  "segs": [ {
    "utf8": "是空間的設計 "
  } ]
}, {
  "tStartMs": 1070018,
  "dDurationMs": 1585,
  "segs": [ {
    "utf8": "就是說他在這個城市"
  } ]
}, {
  "tStartMs": 1071603,
  "dDurationMs": 2303,
  "segs": [ {
    "utf8": "很容易遇到他的記憶"
  } ]
}, {
  "tStartMs": 1073906,
  "dDurationMs": 800,
  "segs": [ {
    "utf8": "我覺得這很重要"
  } ]
}, {
  "tStartMs": 1074706,
  "dDurationMs": 1602,
  "segs": [ {
    "utf8": "然後你空間的設計出來之後"
  } ]
}, {
  "tStartMs": 1076308,
  "dDurationMs": 1985,
  "segs": [ {
    "utf8": "你再去講後面的那一些"
  } ]
}, {
  "tStartMs": 1078293,
  "dDurationMs": 1585,
  "segs": [ {
    "utf8": " 一般性的照顧"
  } ]
}, {
  "tStartMs": 1079878,
  "dDurationMs": 1318,
  "segs": [ {
    "utf8": "那所以我就覺得"
  } ]
}, {
  "tStartMs": 1081196,
  "dDurationMs": 2102,
  "segs": [ {
    "utf8": "像我是隨便舉個例 "
  } ]
}, {
  "tStartMs": 1083298,
  "dDurationMs": 1402,
  "segs": [ {
    "utf8": "我用我自己為出發點"
  } ]
}, {
  "tStartMs": 1084700,
  "dDurationMs": 1068,
  "segs": [ {
    "utf8": "那個時候我在 "
  } ]
}, {
  "tStartMs": 1085768,
  "dDurationMs": 1234,
  "segs": [ {
    "utf8": "我那天去跟光華商場"
  } ]
}, {
  "tStartMs": 1087002,
  "dDurationMs": 1001,
  "segs": [ {
    "utf8": "他們在做座談"
  } ]
}, {
  "tStartMs": 1088003,
  "dDurationMs": 1201,
  "segs": [ {
    "utf8": "因為他們最近生意"
  } ]
}, {
  "tStartMs": 1089204,
  "dDurationMs": 3003,
  "segs": [ {
    "utf8": "很多都被三創之類的拉過去"
  } ]
}, {
  "tStartMs": 1092207,
  "dDurationMs": 1402,
  "segs": [ {
    "utf8": "光華商場是我那一代的記憶"
  } ]
}, {
  "tStartMs": 1093609,
  "dDurationMs": 784,
  "segs": [ {
    "utf8": "其實我也是"
  } ]
}, {
  "tStartMs": 1094393,
  "dDurationMs": 500,
  "segs": [ {
    "utf8": "對"
  } ]
}, {
  "tStartMs": 1094893,
  "dDurationMs": 1502,
  "segs": [ {
    "utf8": "而且光華商場在之前還有"
  } ]
}, {
  "tStartMs": 1096395,
  "dDurationMs": 1601,
  "segs": [ {
    "utf8": "就是因為光華商場那些"
  } ]
}, {
  "tStartMs": 1097996,
  "dDurationMs": 1102,
  "segs": [ {
    "utf8": "之所以會在那一邊"
  } ]
}, {
  "tStartMs": 1099098,
  "dDurationMs": 1501,
  "segs": [ {
    "utf8": "是因為中華商場結束"
  } ]
}, {
  "tStartMs": 1100599,
  "dDurationMs": 1502,
  "segs": [ {
    "utf8": "然後很多人移到那邊去"
  } ]
}, {
  "tStartMs": 1102101,
  "dDurationMs": 1701,
  "segs": [ {
    "utf8": "然後有些移到西寧那邊去"
  } ]
}, {
  "tStartMs": 1103802,
  "dDurationMs": 501,
  "segs": [ {
    "utf8": "對"
  } ]
}, {
  "tStartMs": 1104303,
  "dDurationMs": 700,
  "segs": [ {
    "utf8": "沒錯"
  } ]
}, {
  "tStartMs": 1105003,
  "dDurationMs": 851,
  "segs": [ {
    "utf8": "那我的時候說 "
  } ]
}, {
  "tStartMs": 1105854,
  "dDurationMs": 1051,
  "segs": [ {
    "utf8": "他已經移到那邊來了"
  } ]
}, {
  "tStartMs": 1106905,
  "dDurationMs": 2786,
  "segs": [ {
    "utf8": "我比較沒有中華商場的記憶"
  } ]
}, {
  "tStartMs": 1109691,
  "dDurationMs": 985,
  "segs": [ {
    "utf8": "但是我有的是"
  } ]
}, {
  "tStartMs": 1110676,
  "dDurationMs": 1902,
  "segs": [ {
    "utf8": " 被移到光華商場的記憶"
  } ]
}, {
  "tStartMs": 1112578,
  "dDurationMs": 1268,
  "segs": [ {
    "utf8": "然後你看那時候的入口 "
  } ]
}, {
  "tStartMs": 1113846,
  "dDurationMs": 1234,
  "segs": [ {
    "utf8": "就是在橋下"
  } ]
}, {
  "tStartMs": 1115080,
  "dDurationMs": 1101,
  "segs": [ {
    "utf8": "然後一個光華商場"
  } ]
}, {
  "tStartMs": 1116181,
  "dDurationMs": 1402,
  "segs": [ {
    "utf8": "然後進去那個樓梯很窄"
  } ]
}, {
  "tStartMs": 1117583,
  "dDurationMs": 901,
